import { useState } from 'react';

const rows = [
    { ref: 1042, title: 'VPN drops every 10 minutes', branch: 'North Hub', status: 'In Progress', minutes: -30, unassigned: false },
    { ref: 1043, title: 'Printer on floor 2 shows paper jam', branch: 'Harbor Office', status: 'Open', minutes: 75, unassigned: true },
    { ref: 1044, title: 'New starter laptop setup', branch: 'Central Campus', status: 'Scheduled', minutes: 240, unassigned: false },
    { ref: 1046, title: 'Meeting room display not detected', branch: 'Harbor Office', status: 'Open', minutes: 405, unassigned: true },
    { ref: 1047, title: 'Email signature template update', branch: 'Central Campus', status: 'Resolved', minutes: 60, unassigned: false }
];
const names = ['Active', 'Breached', 'Closing <2h', 'Unassigned'] as const;
type Slice = typeof names[number];
const icons = ['■', '!', '◷', '◇'];
function matches(row: typeof rows[number], name: Slice) {
  if (row.status === 'Resolved' || row.status === 'Closed') return false;
  if (name === 'Active') return true;
  if (name === 'Breached') return row.minutes < 0;
  if (name === 'Closing <2h') return row.minutes >= 0 && row.minutes < 120;
  return row.unassigned;
}

export default function SliceKpiTiles() {
  const [branch, setBranch] = useState('');
  const [selected, setSelected] = useState<Slice | null>(null);
  const scoped = rows.filter(row => !branch || row.branch === branch);
  const visible = scoped.filter(row => !selected || matches(row, selected));
  return <section className="grid gap-3 p-3 text-start text-sm" aria-label="Queue slices">
    <label className="grid gap-1">Branch<select className="min-w-0 rounded-sm border border-strong bg-surface p-2 text-ink" value={branch} onChange={event => setBranch(event.target.value)}>
      <option value="">All branches</option>{[...new Set(rows.map(row => row.branch))].map(item => <option key={item}>{item}</option>)}
    </select></label>
    <div className="grid grid-cols-2 gap-1">{names.map((name, index) => {
      const count = scoped.filter(row => matches(row, name)).length;
      return <button key={name} type="button" aria-label={name + ', ' + count + ' requests'} aria-pressed={selected === name}
        className={'flex min-w-0 items-center justify-between gap-1 rounded-sm border border-strong bg-surface p-2 text-start text-xs aria-pressed:border-accent aria-pressed:bg-accent-tint' + (name === 'Breached' && count > 0 ? ' text-crit' : '')}
        onClick={() => setSelected(selected === name ? null : name)}>
        <span><span aria-hidden="true">{icons[index]}</span> {name}</span><strong className="font-mono tabular-nums">{count}</strong>
      </button>;
    })}</div>
    <p role="status" className="block text-xs text-ink-secondary">{visible.length} matching requests</p>
    <ul className="grid list-none gap-1 p-0">{visible.map(row => <li key={row.ref} className="flex flex-wrap items-start gap-2 border-b border-hairline py-2"><span>
      <strong>#{row.ref} · {row.title}</strong><small className="block text-xs text-ink-secondary">{row.branch} · {row.status}</small>
    </span></li>)}</ul>
  </section>;
}
